css:
.strategyroom-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b2417;
    background:
        radial-gradient(circle at 12% -5%, #fbf6ea 0%, #f4ecda 45%, #efe6d2 100%);
    border-radius: 16px;
    border: 1px solid #e0d2b4;
}

.strategyroom-container * {
    box-sizing: border-box;
}

.strategyroom-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #1d2a44 0%, #243a5e 55%, #2f4a6e 100%);
    color: #f6efde;
    border-radius: 14px;
    margin-bottom: 20px;
    border: 1px solid #16223a;
    box-shadow: 0 12px 30px rgba(29, 42, 68, 0.30);
}

.strategyroom-header h1 {
    margin: 10px 0 12px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.3px;
    color: #fbf3df;
    font-family: Georgia, 'Times New Roman', serif;
}

.strategyroom-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #e7b864;
    background: rgba(231, 184, 100, 0.12);
    border: 1px solid rgba(231, 184, 100, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.strategyroom-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.6;
    color: #d8dfec;
}

.strategyroom-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6b5d40;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.strategyroom-period-counter #currentDay,
.strategyroom-period-counter #maxPeriods {
    font-weight: 800;
    color: #a9762b;
}

.strategyroom-round-name {
    background: rgba(36, 58, 94, 0.10);
    color: #243a5e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.strategyroom-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3b2e;
    background: rgba(154, 59, 46, 0.10);
    border: 1px solid rgba(154, 59, 46, 0.28);
    padding: 4px 12px;
    border-radius: 999px;
}

.strategyroom-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.strategyroom-status-card {
    background: #fffdf7;
    border-radius: 13px;
    padding: 16px 16px 14px;
    border: 1px solid #e6d8bb;
    box-shadow: 0 4px 14px rgba(120, 96, 50, 0.10);
    border-top: 4px solid #c9b079;
}

.strategyroom-card-buyin { border-top-color: #2f6f5e; }
.strategyroom-card-ideas { border-top-color: #3a5a9c; }
.strategyroom-card-legit { border-top-color: #a9762b; }
.strategyroom-card-coherence { border-top-color: #7a4b8a; }

.strategyroom-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7a55;
}

.strategyroom-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2b2417;
    font-variant-numeric: tabular-nums;
}

.strategyroom-card-buyin .strategyroom-value { color: #2f6f5e; }
.strategyroom-card-ideas .strategyroom-value { color: #3a5a9c; }
.strategyroom-card-legit .strategyroom-value { color: #a9762b; }
.strategyroom-card-coherence .strategyroom-value { color: #7a4b8a; }

.strategyroom-sublabel {
    font-size: 0.76rem;
    color: #8a7a55;
    line-height: 1.35;
}

.strategyroom-kpi-high { box-shadow: 0 6px 18px rgba(47, 111, 94, 0.22); }
.strategyroom-kpi-low { border-top-color: #b34a3a !important; }
.strategyroom-kpi-low .strategyroom-value { color: #b34a3a; }

.strategyroom-budget-bar {
    display: flex;
    justify-content: flex-start;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
    background: #243a5e;
    border: 1px solid #16223a;
    color: #e9e0c9;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
}

.strategyroom-budget-bar #budgetDisplay,
.strategyroom-budget-bar #weeksDisplay {
    font-size: 1.02rem;
    letter-spacing: 0.3px;
    color: #e7b864;
}

.strategyroom-budget-sep { color: #6e83a6; }

.strategyroom-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf7;
    border-left: 5px solid #a9762b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #ecdfc3;
    box-shadow: 0 4px 14px rgba(120, 96, 50, 0.10);
}

.strategyroom-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.strategyroom-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #243a5e;
    margin-bottom: 6px;
    font-family: Georgia, 'Times New Roman', serif;
}

.strategyroom-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #4a4231;
}

.strategyroom-briefing-text strong { color: #a9762b; }
.strategyroom-briefing-text em { color: #9a3b2e; font-style: italic; }

.strategyroom-controls {
    background: #fffdf7;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ecdfc3;
    box-shadow: 0 4px 14px rgba(120, 96, 50, 0.10);
}

.strategyroom-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #243a5e;
    border-bottom: 2px solid #ecdfc3;
    padding-bottom: 8px;
    font-family: Georgia, 'Times New Roman', serif;
}

.strategyroom-panel-intro {
    font-size: 0.9rem;
    line-height: 1.55;
    color: #5a5140;
    background: #f7efdd;
    border: 1px solid #ecdfc3;
    border-radius: 9px;
    padding: 10px 14px;
    margin: 0 0 14px;
}

.strategyroom-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a3322;
    margin: 14px 0 6px;
}

.strategyroom-container select,
.strategyroom-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdb98e;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffaf0;
    color: #2b2417;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.strategyroom-container select:focus,
.strategyroom-container input[type="number"]:focus {
    outline: none;
    border-color: #a9762b;
    box-shadow: 0 0 0 3px rgba(169, 118, 43, 0.18);
}

.strategyroom-container select option {
    background-color: #fffaf0;
    color: #2b2417;
}

.strategyroom-stakeholder-grid,
.strategyroom-phase-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin: 6px 0 4px;
}

.strategyroom-stakeholder-row,
.strategyroom-phase-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7efdd;
    border: 1px solid #e6d8bb;
    border-radius: 9px;
    padding: 8px 12px;
}

.strategyroom-stakeholder-name,
.strategyroom-phase-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #4a4231;
}

.strategyroom-stakeholder-row select.strategyroom-incl,
.strategyroom-phase-row select.strategyroom-trans {
    width: 150px;
    flex: 0 0 150px;
}

.strategyroom-cost-readout,
.strategyroom-range-readout {
    font-size: 0.9rem;
    font-weight: 700;
    color: #6b5d40;
    margin-top: 10px;
}

.strategyroom-cost-readout span:last-child {
    color: #a9762b;
    font-weight: 800;
}

.strategyroom-cost-over span:last-child {
    color: #b34a3a;
}

.strategyroom-hint {
    font-size: 0.8rem;
    color: #8a7a55;
    margin-top: 6px;
    line-height: 1.45;
}

.strategyroom-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.strategyroom-container .btn-primary {
    background: linear-gradient(135deg, #a9762b 0%, #d39a44 100%);
    border: none;
    color: #2b1c08;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(169, 118, 43, 0.32);
}

.strategyroom-container .btn-primary:hover {
    filter: brightness(1.06);
}

.strategyroom-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cdb98e;
    color: #6b5d40;
    background: transparent;
}

.strategyroom-coach {
    background: linear-gradient(160deg, #1d2a44 0%, #243a5e 100%);
    color: #e3e9f3;
    border: 1px solid #16223a;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(29, 42, 68, 0.28);
}

.strategyroom-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7b864;
    margin-bottom: 8px;
}

.strategyroom-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
}

.strategyroom-coach-body strong { color: #e7b864; }
.strategyroom-coach-body em { color: #f0a98e; font-style: italic; }

.strategyroom-history,
.strategyroom-chart {
    background: #fffdf7;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ecdfc3;
    box-shadow: 0 4px 14px rgba(120, 96, 50, 0.10);
}

.strategyroom-history h3,
.strategyroom-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #243a5e;
    font-family: Georgia, 'Times New Roman', serif;
}

.strategyroom-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a4231;
}

.strategyroom-container table#usfHistoryTable th {
    background: #243a5e;
    color: #e7b864;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #16223a;
}

.strategyroom-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #ecdfc3;
    color: #4a4231;
}

.strategyroom-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf3e4;
}

.strategyroom-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .strategyroom-container {
        padding: 14px;
    }
    .strategyroom-header h1 {
        font-size: 1.7rem;
    }
    .strategyroom-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .strategyroom-value {
        font-size: 2rem;
    }
    .strategyroom-clock {
        margin-left: 0;
    }
    .strategyroom-period-counter {
        font-size: 0.88rem;
    }
    .strategyroom-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .strategyroom-budget-sep { display: none; }
    .strategyroom-stakeholder-row,
    .strategyroom-phase-row {
        flex-wrap: wrap;
    }
    .strategyroom-stakeholder-row select.strategyroom-incl,
    .strategyroom-phase-row select.strategyroom-trans {
        width: 100%;
        flex: 1 1 100%;
    }
    .strategyroom-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ── v1.1.0 completion scorecard (append-only, namespaced .sr-cm-*, parchment/navy/gold) ── */
.sr-cm { margin-top: 8px; }
.sr-cm-incomplete { text-align: center; color: #6b5d40; font-size: 1rem; padding: 18px; }
.sr-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.sr-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #1d2a44 0%, #243a5e 55%, #a9762b 135%); color: #fffdf7; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(29, 42, 68, 0.28); }
.sr-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.sr-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.82; }
.sr-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #e7b864; }
.sr-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #fffdf7; border: 1px solid #e6d8bb; border-left: 5px solid #a9762b; border-radius: 14px; padding: 16px 20px; }
.sr-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #8a7a55; }
.sr-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #243a5e; line-height: 1.15; }
.sr-cm-section { margin-bottom: 16px; }
.sr-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #8a7a55; margin-bottom: 8px; }
.sr-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.sr-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.sr-cm-ok { background: rgba(47, 111, 94, 0.14); color: #2f6f5e; border-color: rgba(47, 111, 94, 0.4); }
.sr-cm-no { background: rgba(154, 59, 46, 0.12); color: #9a3b2e; border-color: rgba(154, 59, 46, 0.4); }
.sr-cm-ico { font-weight: 800; }
.sr-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; }
.sr-cm-kpi { background: #fffdf7; border: 1px solid #e6d8bb; border-top: 4px solid #a9762b; border-radius: 12px; padding: 14px 12px; text-align: center; }
.sr-cm-kpi-val { font-size: 1.6rem; font-weight: 800; color: #243a5e; line-height: 1; }
.sr-cm-kpi-lbl { margin-top: 6px; font-size: 0.82rem; font-weight: 700; color: #4a4231; }
.sr-cm-kpi-sub { margin-top: 2px; font-size: 0.7rem; color: #8a7a55; }
.sr-cm-insights { margin: 0; padding-left: 18px; color: #4a4231; }
.sr-cm-insights li { margin: 4px 0; font-size: 0.92rem; line-height: 1.45; }
@media (max-width: 560px) { .sr-cm-head { flex-direction: column; } .sr-cm-score { min-width: 0; } }

