(function() {
    'use strict';

    class StrategyRoomAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Open the Strategy Room`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Lumen Atlas Foundation, GBP).
            this.PART_BUDGET = 600;   // GBP 600K participation budget cap
            this.WEEK_CAP = 10;       // 10-week process window
            this.AI_OFFER = 20;       // GBP 20M / year AI-licensing offer

            // Per-level participation cost (GBP K) and time (weeks).
            this.COST = { cocreate: 120, consult: 45, inform: 8, exclude: 0 };
            this.WEEKS = { cocreate: 4, consult: 1.5, inform: 0.3, exclude: 0 };

            // The nine stakeholder groups (DOM input ids).
            this.GROUPS = [
                `core`, `casual`, `chapter`, `major`, `small`, `staff`, `board`, `partners`, `readers`
            ];
            // Salience weights (Mitchell/Agle/Wood): excluding a high-salience group
            // costs disproportionate legitimacy. small donors = financial salience.
            this.REVOLT_GROUPS = { core: 1, small: 1 };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    buyin: 35,        // stakeholder support for process & plan
                    ideas: 30,        // diversity & strength of input gathered
                    legit: 40,        // community sense the process was fair
                    coherence: 45,    // strategic focus the Board will test
                    budgetUsed: 0,    // GBP K of participation budget committed (R1)
                    weeksUsed: 0,     // weeks of process used (R1)
                    aiStance: `pending`,   // accept / conditional / refuse
                    overReached: false,    // blew the participation budget/time
                    averaged: false,       // tried to adopt all four camps
                    capitulated: false,    // dropped the clause by ultimatum
                    wonVoteLostRoom: false, // approved by Board but lost the community trustees
                    buyinHistory: [35],
                    ideasHistory: [30],
                    legitHistory: [40],
                    coherenceHistory: [45],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately wrong-leaning mix —
                // a blind click-through must underperform, not auto-win.
                state.decisions = {
                    // R1 — everyone co-create (maximal inclusion = Common Error 1).
                    core: `cocreate`, casual: `cocreate`, chapter: `cocreate`,
                    major: `cocreate`, small: `cocreate`, staff: `cocreate`,
                    board: `cocreate`, partners: `cocreate`, readers: `cocreate`,
                    // R2 — premature transparency on the figure (Common Error 2).
                    framing: `public`, options: `public`, financial: `public`,
                    recommendation: `public`, channels: `forumonly`, publish: `week2`,
                    // R3 — average everything (Common Error 3).
                    camps: `all`, priorities: `6`, ai: `accept`, feedback: `silence`,
                    // R4 — content-only pitch + capitulation (Common Errors 4 & 5).
                    pitch: `content`, freeze: `capitulate`, governance: `none`, statement: `topdown`
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                let allRead = true;
                this.GROUPS.forEach((g) => {
                    const el = document.getElementById(g + `Input`);
                    if (el) { decisions[g] = el.value; } else { allRead = false; }
                });
                if (!allRead) { warn(`warn_groups_missing`); return false; }
                // Budget & time guard: the configuration must fit the cap (the
                // facilitator decision tree teaches the cost curve — but we let
                // a deliberate over-reach through with a flagged consequence only
                // if NOT every group is co-create; an all-co-create plan is blocked
                // because it cannot physically be delivered.)
                const cost = this._r1Cost(decisions);
                const allCo = this.GROUPS.every((g) => decisions[g] === `cocreate`);
                if (allCo) { warn(`warn_all_cocreate`); return false; }
                if (cost.weeks > this.WEEK_CAP + 6) { warn(`warn_time_blown`); return false; }
                if (!Number.isFinite(cost.money)) { warn(`warn_groups_missing`); return false; }
            } else if (round === 2) {
                const ids = { framing: `framingInput`, options: `optionsInput`, financial: `financialInput`, recommendation: `recommendationInput`, channels: `channelsInput`, publish: `publishInput` };
                let ok = true;
                Object.keys(ids).forEach((k) => {
                    const el = document.getElementById(ids[k]);
                    if (el) { decisions[k] = el.value; } else { ok = false; }
                });
                if (!ok) { warn(`warn_phase_missing`); return false; }
            } else if (round === 3) {
                const ids = { camps: `campsInput`, priorities: `prioritiesInput`, ai: `aiInput`, feedback: `feedbackInput` };
                let ok = true;
                Object.keys(ids).forEach((k) => {
                    const el = document.getElementById(ids[k]);
                    if (el) { decisions[k] = el.value; } else { ok = false; }
                });
                if (!ok) { warn(`warn_recon_missing`); return false; }
                const p = parseInt(decisions.priorities, 10);
                if (!Number.isFinite(p) || p < 1) { warn(`warn_recon_missing`); return false; }
            } else if (round === 4) {
                const ids = { pitch: `pitchInput`, freeze: `freezeInput`, governance: `governanceInput`, statement: `statementInput` };
                let ok = true;
                Object.keys(ids).forEach((k) => {
                    const el = document.getElementById(ids[k]);
                    if (el) { decisions[k] = el.value; } else { ok = false; }
                });
                if (!ok) { warn(`warn_vote_missing`); return false; }
            }
            return true;
        }

        _r1Cost(d) {
            let money = 0, weeks = 0;
            this.GROUPS.forEach((g) => {
                const lvl = d[g] || `exclude`;
                money += (this.COST[lvl] || 0);
                weeks += (this.WEEKS[lvl] || 0);
            });
            return { money: money, weeks: Math.round(weeks * 10) / 10 };
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let buyinDelta = 0, ideasDelta = 0, legitDelta = 0, coherenceDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Map the room: inclusion depth vs. cost curve (Common Error 1).
                const cost = this._r1Cost(d);
                ds.budgetUsed = cost.money;
                ds.weeksUsed = cost.weeks;

                // Depth of inclusion lifts buy-in, idea diversity and legitimacy,
                // but too many deep voices erodes coherence (wisdom-of-crowds boundary).
                let coCount = 0, consultCount = 0, informCount = 0, excludeCount = 0;
                this.GROUPS.forEach((g) => {
                    const lvl = d[g];
                    if (lvl === `cocreate`) coCount++;
                    else if (lvl === `consult`) consultCount++;
                    else if (lvl === `inform`) informCount++;
                    else excludeCount++;
                });

                buyinDelta += coCount * 4 + consultCount * 2 + informCount * 0.5;
                ideasDelta += coCount * 4 + consultCount * 3 + informCount * 1;
                legitDelta += coCount * 3 + consultCount * 2 + informCount * 1;
                // Coherence falls as the room fills with deep voices.
                coherenceDelta -= coCount * 2;

                // Cost-curve consequence (the decision-tree's central lesson).
                const overMoney = cost.money > this.PART_BUDGET;
                const overTime = cost.weeks > this.WEEK_CAP;
                if (overMoney || overTime) {
                    ds.overReached = true;
                    coherenceDelta -= 12;
                    buyinDelta -= 6;     // a co-creation you cannot deliver erodes trust
                    coachKey = `coach_r1_overreach`;
                } else if (cost.money <= this.PART_BUDGET * 0.5 && coCount <= 1) {
                    // Under-investing in inclusion reads as a closed process.
                    legitDelta -= 6; ideasDelta -= 4; coachKey = `coach_r1_thin`;
                }

                // Salience: excluding a revolt-trigger group (core editors / small donors).
                let revolt = false;
                if (d.core === `exclude`) { legitDelta -= 16; buyinDelta -= 10; revolt = true; coachKey = `coach_r1_excludecore`; }
                if (d.small === `exclude`) { legitDelta -= 8; buyinDelta -= 12; revolt = true; if (coachKey === `coach_default` || coachKey === `coach_r1_thin`) coachKey = `coach_r1_excludesmall`; }

                // The model answer: deep on the highest-salience few, lighter elsewhere,
                // within budget — and the Board co-created/consulted (they hold the deadline).
                const coreDeep = (d.core === `cocreate` || d.core === `consult`);
                const smallInformed = (d.small !== `exclude`);
                const boardIn = (d.board === `cocreate` || d.board === `consult`);
                const wellTargeted = coreDeep && smallInformed && boardIn && !overMoney && !overTime && coCount >= 2 && coCount <= 4;
                if (wellTargeted) {
                    coherenceDelta += 6; legitDelta += 6;
                    if (coachKey === `coach_default`) coachKey = `coach_r1_targeted`;
                }

                summaryKey = wellTargeted ? `sum_r1_good` :
                             (ds.overReached ? `sum_r1_overreach` :
                             (revolt ? `sum_r1_revolt` : `sum_r1_weak`));
            } else if (round === 2) {
                // Set the glass: phase-dependent transparency (Common Error 2).
                // Open generation, protected synthesis: framing & recommendation public,
                // financial modelling closed/summary until conditions attached.
                const openFraming = (d.framing === `public`);
                const openRec = (d.recommendation === `public` || d.recommendation === `summary`);
                const financialOpenEarly = (d.financial === `public`);

                // Transparency on framing & recommendation builds legitimacy.
                if (openFraming) legitDelta += 6;
                if (openRec) legitDelta += 6;
                if (d.recommendation === `closed`) { legitDelta -= 10; coachKey = `coach_r2_closedrec`; }

                // Premature transparency on the half-formed £20M figure is the disaster.
                if (financialOpenEarly && d.publish === `week2`) {
                    legitDelta -= 6; coherenceDelta -= 12; buyinDelta -= 8;
                    coachKey = `coach_r2_premature`;
                } else if (d.financial === `closed`) {
                    coherenceDelta += 8;   // protected modelling preserves coherence
                } else if (d.financial === `summary`) {
                    coherenceDelta += 4; legitDelta += 2;
                }

                // Timing of the £20M figure (the explicit phase-transparency lever).
                switch (d.publish) {
                    case `recommendation`: coherenceDelta += 8; legitDelta += 6; buyinDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r2_timing`; break;
                    case `week2`: if (coachKey !== `coach_r2_premature`) { coherenceDelta -= 8; legitDelta -= 4; coachKey = `coach_r2_premature`; } break;
                    case `never`: legitDelta -= 8; buyinDelta -= 4; coachKey = `coach_r2_never`; break;
                }

                // Channel mix — wisdom-of-crowds boundary: open generation, structured synthesis.
                switch (d.channels) {
                    case `mixed`: ideasDelta += 12; legitDelta += 6; buyinDelta += 4; if (coachKey === `coach_default` || coachKey === `coach_r2_timing`) coachKey = `coach_r2_mixed`; break;
                    case `surveys`: ideasDelta += 6; legitDelta += 3; break;
                    case `forumonly`: ideasDelta += 4; coherenceDelta -= 6; if (coachKey === `coach_default`) coachKey = `coach_r2_forum`; break;
                    case `panelsonly`: ideasDelta += 2; legitDelta -= 8; coherenceDelta += 2; coachKey = `coach_r2_panels`; break;
                }

                const goodGlass = openFraming && openRec && (d.financial !== `public` || d.publish !== `week2`) && d.publish === `recommendation` && d.channels === `mixed`;
                summaryKey = goodGlass ? `sum_r2_good` :
                             ((financialOpenEarly && d.publish === `week2`) ? `sum_r2_premature` : `sum_r2_weak`);
            } else if (round === 3) {
                // Reconcile the noise: integrate by choosing, not averaging (Common Error 3).
                const prio = parseInt(d.priorities, 10);

                // Camp selection → coherence (a spine of two chosen camps).
                switch (d.camps) {
                    case `all`: ds.averaged = true; coherenceDelta -= 18; legitDelta -= 4; coachKey = `coach_r3_all`; break;
                    case `licensepremium`: coherenceDelta += 12; ideasDelta += 4; break;
                    case `puristpremium`: coherenceDelta += 12; legitDelta += 4; break;
                    case `statusquo`: coherenceDelta += 4; ideasDelta -= 6; buyinDelta -= 4; coachKey = `coach_r3_statusquo`; break;
                }

                // Number of priorities — focus is the Board's test.
                if (prio <= 3) { coherenceDelta += 8; }
                else { coherenceDelta -= 10; if (!ds.averaged) coachKey = `coach_r3_toomany`; }

                // The AI-licensing question.
                ds.aiStance = d.ai;
                switch (d.ai) {
                    case `conditional`: coherenceDelta += 6; legitDelta += 8; buyinDelta += 6; if (coachKey === `coach_default`) coachKey = `coach_r3_conditional`; break;
                    case `accept`: coherenceDelta += 4; legitDelta -= 10; buyinDelta -= 6; if (coachKey === `coach_default`) coachKey = `coach_r3_accept`; break;
                    case `refuse`: legitDelta += 8; coherenceDelta -= 4; ideasDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r3_refuse`; break;
                }

                // "You were heard" — closing the loop with rejected camps confers legitimacy.
                switch (d.feedback) {
                    case `heard`: legitDelta += 12; buyinDelta += 8; if (coachKey === `coach_default` || coachKey === `coach_r3_conditional`) coachKey = `coach_r3_heard`; break;
                    case `generic`: legitDelta += 2; break;
                    case `silence`: legitDelta -= 10; buyinDelta -= 6; coachKey = `coach_r3_silence`; break;
                }

                const goodSpine = (d.camps === `licensepremium` || d.camps === `puristpremium`) && prio <= 3 && d.feedback === `heard` && d.ai !== `accept`;
                summaryKey = goodSpine ? `sum_r3_good` :
                             (ds.averaged ? `sum_r3_averaged` : `sum_r3_weak`);
            } else if (round === 4) {
                // The 15 June vote: win approval AND legitimacy (Common Errors 4 & 5).
                switch (d.pitch) {
                    case `both`: buyinDelta += 10; legitDelta += 8; coherenceDelta += 4; coachKey = `coach_r4_both`; break;
                    case `content`: buyinDelta += 6; legitDelta -= 12; ds.wonVoteLostRoom = true; coachKey = `coach_r4_content`; break;
                    case `legitimacy`: legitDelta += 6; coherenceDelta -= 8; buyinDelta -= 2; coachKey = `coach_r4_legitonly`; break;
                }

                // The live editing-freeze threat — reconcile without surrendering.
                switch (d.freeze) {
                    case `conditional`: legitDelta += 10; coherenceDelta += 6; buyinDelta += 6; if (coachKey === `coach_r4_both`) coachKey = `coach_r4_held`; break;
                    case `capitulate`: ds.capitulated = true; coherenceDelta -= 16; buyinDelta -= 4; legitDelta -= 2; coachKey = `coach_r4_capitulate`; break;
                    case `ignore`: legitDelta -= 12; buyinDelta -= 8; coachKey = `coach_r4_ignore`; break;
                }

                // Governance mechanism that carries the plan through 2031.
                switch (d.governance) {
                    case `standing`: legitDelta += 8; coherenceDelta += 6; buyinDelta += 4; break;
                    case `annual`: legitDelta += 3; break;
                    case `none`: legitDelta -= 6; coherenceDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r4_nogov`; break;
                }

                // Community-facing legitimacy statement.
                switch (d.statement) {
                    case `honest`: legitDelta += 10; buyinDelta += 6; if (coachKey === `coach_r4_both` || coachKey === `coach_r4_held`) coachKey = `coach_r4_landed`; break;
                    case `spin`: legitDelta -= 10; buyinDelta -= 4; coachKey = `coach_r4_spin`; break;
                    case `topdown`: legitDelta -= 6; coachKey = `coach_r4_topdown`; break;
                }

                const landed = d.pitch === `both` && d.freeze === `conditional` && d.governance === `standing` && d.statement === `honest`;
                summaryKey = landed ? `sum_r4_good` :
                             (ds.capitulated ? `sum_r4_capitulate` :
                             (ds.wonVoteLostRoom ? `sum_r4_lostroom` : `sum_r4_weak`));
            }

            // Apply deltas, clamped 0–100.
            ds.buyin = Math.max(0, Math.min(100, Math.round(ds.buyin + buyinDelta)));
            ds.ideas = Math.max(0, Math.min(100, Math.round(ds.ideas + ideasDelta)));
            ds.legit = Math.max(0, Math.min(100, Math.round(ds.legit + legitDelta)));
            ds.coherence = Math.max(0, Math.min(100, Math.round(ds.coherence + coherenceDelta)));

            ds.buyinHistory.push(ds.buyin);
            ds.ideasHistory.push(ds.ideas);
            ds.legitHistory.push(ds.legit);
            ds.coherenceHistory.push(ds.coherence);

            // v1.1.0 — persist the composite where the gradebook reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                buyin: ds.buyin,
                buyinDelta: Math.round(buyinDelta),
                ideas: ds.ideas,
                ideasDelta: Math.round(ideasDelta),
                legit: ds.legit,
                legitDelta: Math.round(legitDelta),
                coherence: ds.coherence,
                coherenceDelta: Math.round(coherenceDelta),
                budgetUsed: ds.budgetUsed,
                weeksUsed: ds.weeksUsed,
                overReached: ds.overReached,
                averaged: ds.averaged,
                capitulated: ds.capitulated,
                wonVoteLostRoom: ds.wonVoteLostRoom,
                aiStance: ds.aiStance,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: _score,
                overallScore: _score
            };
        }

        _fmtMoneyK(v) {
            // GBP in thousands: English "£600K", Spanish "600 K£".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v));
            if (lang === `es`) {
                return `${n} K£`;
            }
            return `£${n}K`;
        }

        _fmtWeeks(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v) * 10) / 10;
            const str = (lang === `es`) ? n.toFixed(1).replace(`.`, `,`) : n.toFixed(1);
            return `${str} ${window.mySimulation.t(`wks_unit`)}`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            const kpiFmt = (id, cls) => (v) => {
                const card = document.querySelector(`.` + cls);
                const n = Math.round(Number(v));
                if (card) {
                    card.classList.toggle(`strategyroom-kpi-high`, n >= 70);
                    card.classList.toggle(`strategyroom-kpi-low`, n <= 25);
                }
                return n;
            };

            uiManager.bind(`buyinDisplay`, `domainState.buyin`, kpiFmt(`buyinDisplay`, `strategyroom-card-buyin`));
            uiManager.bind(`ideasDisplay`, `domainState.ideas`, kpiFmt(`ideasDisplay`, `strategyroom-card-ideas`));
            uiManager.bind(`legitDisplay`, `domainState.legit`, kpiFmt(`legitDisplay`, `strategyroom-card-legit`));
            uiManager.bind(`coherenceDisplay`, `domainState.coherence`, kpiFmt(`coherenceDisplay`, `strategyroom-card-coherence`));

            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoneyK(Number(v)) + ` / ` + self._fmtMoneyK(self.PART_BUDGET);
            });
            uiManager.bind(`weeksDisplay`, `domainState.weeksUsed`, (v) => {
                return self._fmtWeeks(Number(v)) + ` / ` + self._fmtWeeks(self.WEEK_CAP);
            });

            // Live Round-1 cost readout (budget + weeks).
            const recompute = function() {
                const d = {};
                self.GROUPS.forEach((g) => {
                    const el = document.getElementById(g + `Input`);
                    d[g] = el ? el.value : `exclude`;
                });
                const cost = self._r1Cost(d);
                const readout = document.getElementById(`r1CostReadout`);
                if (readout) {
                    readout.textContent = self._fmtMoneyK(cost.money) + ` · ` + self._fmtWeeks(cost.weeks);
                }
                const wrap = document.querySelector(`.strategyroom-cost-readout`);
                if (wrap) {
                    const over = cost.money > self.PART_BUDGET || cost.weeks > self.WEEK_CAP;
                    wrap.classList.toggle(`strategyroom-cost-over`, over);
                }
            };
            self.GROUPS.forEach((g) => {
                const el = document.getElementById(g + `Input`);
                if (el) el.addEventListener(`change`, recompute);
            });
            recompute();
        }

        getChartConfig() {
