        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.buyinHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                strategyChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.buyinHistory },
                        { data: ds.legitHistory },
                        { data: ds.coherenceHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const buyin = Math.round(ds.buyin);
            const ideas = Math.round(ds.ideas);
            const legit = Math.round(ds.legit);
            const coherence = Math.round(ds.coherence);
            const balance = Math.min(legit, coherence);
            return Math.round(buyin * 0.22 + ideas * 0.16 + legit * 0.24 + coherence * 0.24 + balance * 0.14);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const buyin = Math.round(ds.buyin);
            const ideas = Math.round(ds.ideas);
            const legit = Math.round(ds.legit);
            const coherence = Math.round(ds.coherence);

            // Composite: the central tension is legitimacy AND coherence together.
            // High performers protect both; a min-style term punishes lopsided plans.
            const balance = Math.min(legit, coherence);
            const composite = this._composite(ds);

            const approved = coherence >= 55;                 // the Board's focus test
            const legitimate = legit >= 60;                   // the community's fairness test
            const bothHeld = approved && legitimate && balance >= 55;
            const exposed = ds.averaged || ds.capitulated || ds.wonVoteLostRoom || ds.overReached;

            // v1.1.0 — tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_stalled`;
            if (bothHeld && composite >= 75) tierKey = `grade_mastered`;
            else if (bothHeld) tierKey = `grade_held`;
            else if (approved && !legitimate) tierKey = `grade_lostroom`;
            else if (legitimate && !approved) tierKey = `grade_unfocused`;
            else if (ds.overReached) tierKey = `grade_blown`;
            else if (composite >= 55) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (bothHeld) insights.push(window.mySimulation.t(`insight_mastered`));
            else if (approved && !legitimate) insights.push(window.mySimulation.t(`insight_lostroom`));
            else if (legitimate && !approved) insights.push(window.mySimulation.t(`insight_unfocused`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.overReached) insights.push(window.mySimulation.t(`insight_overreach`));
            if (ds.averaged) insights.push(window.mySimulation.t(`insight_averaged`));
            if (ds.capitulated) insights.push(window.mySimulation.t(`insight_capitulate`));
            if (ds.aiStance === `conditional`) insights.push(window.mySimulation.t(`insight_conditional`));
            if (legit >= 70 && coherence >= 70) insights.push(window.mySimulation.t(`insight_bothdials`));

            return {
                buyin: buyin,
                ideas: ideas,
                legit: legit,
                coherence: coherence,
                approved: approved,
                legitimate: legitimate,
                bothHeld: bothHeld,
                exposed: exposed,
                averaged: !!ds.averaged,
                overReached: !!ds.overReached,
                capitulated: !!ds.capitulated,
                wonVoteLostRoom: !!ds.wonVoteLostRoom,
                budgetUsed: ds.budgetUsed,
                weeksUsed: ds.weeksUsed,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="sr-cm"><p class="sr-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="sr-cm-chip ` + (ok ? `sr-cm-ok` : `sr-cm-no`) + `">` +
                `<span class="sr-cm-ico">` + (ok ? `✓` : `✕`) + `</span>` + label + ` · ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="sr-cm-kpi"><div class="sr-cm-kpi-val">` + val +
                `</div><div class="sr-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="sr-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="sr-cm">` +
  `<div class="sr-cm-head">` +
    `<div class="sr-cm-score"><div class="sr-cm-score-num">` + Math.round(s.composite) +
       `<span class="sr-cm-score-den">/100</span></div>` +
       `<div class="sr-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="sr-cm-verdict"><div class="sr-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="sr-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="sr-cm-section"><div class="sr-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="sr-cm-chips">` + chip(!!s.approved, t(`cm_t_approved`)) + chip(!!s.legitimate, t(`cm_t_legit`)) +
      chip(!s.averaged, t(`cm_t_spine`)) + chip(!s.overReached, t(`cm_t_budget`)) + `</div></div>` +
  `<div class="sr-cm-section"><div class="sr-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="sr-cm-kpis">` +
      kpi(t(`cm_k_buyin`), Math.round(s.buyin), t(`cm_sub_buyin`)) +
      kpi(t(`cm_k_ideas`), Math.round(s.ideas), t(`cm_sub_ideas`)) +
      kpi(t(`cm_k_legit`), Math.round(s.legit), t(`cm_sub_legit`)) +
      kpi(t(`cm_k_coherence`), Math.round(s.coherence), t(`cm_sub_coherence`)) +
    `</div></div>` +
  (insights ? `<div class="sr-cm-section"><div class="sr-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="sr-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overReached && state.currentPeriod <= 2) return window.mySimulation.t(`hint_overreach`);
            if (ds.averaged) return window.mySimulation.t(`hint_averaged`);
            if (ds.capitulated) return window.mySimulation.t(`hint_capitulate`);
            if (ds.coherence < 35 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_coherence`);
            if (ds.legit < 35) return window.mySimulation.t(`hint_legit`);
            if (ds.legit >= 65 && ds.coherence >= 65) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.buyin`, label: `Buy-in`, i18nKey: `col_buyin`, formatter: (v) => Math.round(v) },
                { key: `results.legit`, label: `Legitimacy`, i18nKey: `col_legit`, formatter: (v) => Math.round(v) },
                { key: `results.coherence`, label: `Coherence`, i18nKey: `col_coherence`, formatter: (v) => Math.round(v) }
            ];
        }

